      "exceptions": [],
      "grounding": [
        {
          "end_line": 878,
          "quote": "id(o_n) binds (\n  exact traversal-occurrence-profile basis,\n  application identity,\n  traversal identity,\n  functor-kind identity,\n  subject-binding identity,\n  intended-outcome identity,\n  declared lineage inputs,\n  declared identity-dependency inputs\n)",
