      "key": "mutable_subject_effect",
      "label": "Mutable-subject effect model"
    },
    {
      "conditions": [],
      "definition": "EventFrontier identifies an exact event population under profile basis, scope and precedence law. Projection identifies an interpretation of one exact frontier through a rule, selected relation identities, boundary identities and residual identities. This profile Projection is distinct from the world-model Projection described elsewhere in the supplied corpus.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1228,
          "quote": "Frontier identity binds\nthe profile basis, scope, precedence law, sorted event identities, and event\ncontent digests. Projection identity binds the exact frontier, projection\nrule, selected relation ids, boundary ids, and residual ids.",
