    {
      "conditions": [],
      "definition": "UX Method is the named method document for UX realization. Its heading and profile-binding marker introduce the following substantive sections without independently establishing adoption.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3,
          "quote": "# UX Method\n\n<!-- STDO3_PROFILE_BINDING_START -->",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/UX_METHOD.md#UX%20Method",
