    {
      "conditions": [],
      "definition": "World Model Object is deliberately weak shorthand for something treated as real in an institutional operating model, useful during observation, extraction, review and discussion. It is weaker than Markov Object and is not the preferred name for the governed identity-bearing published unit.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 658,
          "quote": "A generic shorthand for something treated as real in the institutional\noperating model.\n\nThis term is intentionally weaker than `Markov Object`. It is useful during\nobservation, extraction, review, and discussion. It is not the preferred name\nfor the primary published semantic unit once the builder has constructed a\ngoverned identity-bearing cut.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/WORLD_MODEL_METHOD.md#World%20Model%20Method%2FMethod%20Units%2FWorld%20Model%20Object",
