    {
      "conditions": [],
      "definition": "Assurance is the governed basis for accepting a traced source observation as a qualified semantic claim; it explains lawful world-model truth rather than mere raw observation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 666,
          "quote": "The governed basis on which a traced source observation is accepted as a\nqualified semantic claim.\n\nAssurance answers why a claim is lawful world-model truth rather than merely a\nraw observation.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/WORLD_MODEL_METHOD.md#World%20Model%20Method%2FMethod%20Units%2FAssurance",
