    },
    {
      "conditions": [],
      "definition": "Attribute Ledger is an append-only ordered record of qualified attribute claims over a stable object identity. Entries may carry observed or derived values, interpreted meanings, rules or constraints, topology or relations, provenance or authority, and effective, observed and publication coordinates.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 682,
          "quote": "An append-only ordered record of qualified attribute claims over a stable\nobject identity.\n\nAttribute-ledger entries may carry:\n\n- observed values\n- derived values\n- interpreted meanings\n- rule or constraint claims\n- topology or relation claims\n- provenance and authority claims\n- effective, observed, and publication coordinates",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/WORLD_MODEL_METHOD.md#World%20Model%20Method%2FMethod%20Units%2FAttribute%20Ledger",
